#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>

#include "lwan-config.h"

static bool
dump(struct config *config, struct config_line *line, int indent_level)
{
    if (indent_level > 64)
        return false;

    while (config_read_line(config, line)) {
        switch (line->type) {
        case CONFIG_LINE_TYPE_LINE:
            break;
        case CONFIG_LINE_TYPE_SECTION_END:
            if (indent_level == 0)
                return false;
            return true;
        case CONFIG_LINE_TYPE_SECTION:
            if (!dump(config, line, indent_level + 1))
                return false;
            break;
        }
    }

    if (config_last_error(config)) {
        fprintf(stderr, "Error while reading configuration file (line %d): %s\n",
                config_cur_line(config), config_last_error(config));
        return false;
    }

    return true;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file>\n", argv[0]);
        return 1;
    }

    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) { perror("open"); return 1; }

    struct stat st;
    fstat(fd, &st);

    static uint8_t static_data[32768];
    size_t size = st.st_size;
    if (size > sizeof(static_data))
        size = sizeof(static_data);

    read(fd, static_data, size);
    close(fd);

    struct config *config = config_open_for_fuzzing(static_data, size);
    if (!config)
        return 1;

    struct config_line line;
    bool dumped = dump(config, &line, 0);

    config_close(config);
    return dumped ? 0 : 1;
}
EOF

